 // Define Parameters
 // Note: These must match the values in the sdram_lb_defines_0.v file

parameter EF_AXI_PAR      = 1;
parameter EF_RMW_PAR      = 1;
parameter EF_ECC_PAR      = 1;
parameter EF_MPFE_PAR     = 1;
parameter EF_LB_PAR       = 0;
parameter AXI0_ENABLE_PAR = 1;
