  ///////////////////////////////////////////////////////////////////////////////////////
 //
 // Parameters
 //
     parameter COREDDRMEMCTRLR_INST_NO     = 0;
     parameter FAMILY                      = 26;
     parameter DSIZE                       = 512;
     parameter NIBBLE_DEVICES              = 0;
     parameter FREQ_RATIO                  = 4;  // Set if using half rate operation
     parameter DISABLE_BURST_TERMINATE     = 0;  // Disables burst terminates(required for some PHYs), only applicable for SDR/DDR
     parameter NUMBER_OF_RANKS             = 8;  // only 8 or 16 supported, controls width of rank-sized controller input and output ports
     parameter CTRLR_RANKS                 = 4; // Sets number of ranks controller will actually support. Set to actual number
                                                              //    of required ranks to eliminate unnecessary controller logic.
     parameter BANK_GROUP_ADDR_WIDTH       = 2;  //Sets the number of bank groups in the memory device(#bank_groups = 2**BANK_GROUP_ADDR_WIDTH)

     // AXI parameters
     parameter AXI_SLAVE_TYPE              = 0;
     parameter AXI_SLAVE_ID_WIDTH          = 4;
     parameter AXI_ADDR_WIDTH              = 32;
     parameter AXI_DATA_WIDTH              = 512;
     parameter AXI_LEN_WIDTH               = 4;     // width of awlen/arlen ports
     parameter AXI_AWUSERTAG_EN            = 0;     // enable/disable of awusertag, 0 - disable, 1 - enable
     parameter AXI_AWUSERTAG_WIDTH         = 4;     // width of awusertag and busertag ports
     parameter AXI_ECC_SUPPORT             = 0;     // enables ecc support in the axi module
     parameter AXI_SINGLE_CLOCK_MODE       = 0;     // set when AXI and Memory Controller Share clock domains, for optimized latency
parameter AXI_ENABLE_INTRAPORT_REORDER = 0;    // enables support for intraport reordering

     parameter ADDR_MAP_SIG_BITS           = 10;
     parameter MAX_SN_WIDTH                = 2;      // equal to the smallest AXIx_SN_WIDTH setting, largest is 5
     parameter TAG_WIDTH                   =(EF_AXI_PAR == 1) ? 36+MAX_SN_WIDTH+AXI_SLAVE_ID_WIDTH+AXI_LEN_WIDTH : 1; // Tag bit width

     parameter AXI0_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI0_WRITE_ONLY             = 0;
     parameter AXI0_READ_ONLY              = 0;
     parameter AXI0_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI0_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI0_CMD_FIFO_AWIDTH        = 4;

     parameter AXI1_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI1_WRITE_ONLY             = 0;
     parameter AXI1_READ_ONLY              = 0;
     parameter AXI1_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI1_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI1_CMD_FIFO_AWIDTH        = 4;

     parameter AXI2_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI2_WRITE_ONLY             = 0;
     parameter AXI2_READ_ONLY              = 0;
     parameter AXI2_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI2_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI2_CMD_FIFO_AWIDTH        = 4;

     parameter AXI3_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI3_WRITE_ONLY             = 0;
     parameter AXI3_READ_ONLY              = 0;
     parameter AXI3_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI3_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI3_CMD_FIFO_AWIDTH        = 4;

     parameter AXI4_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI4_WRITE_ONLY             = 0;
     parameter AXI4_READ_ONLY              = 0;
     parameter AXI4_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI4_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI4_CMD_FIFO_AWIDTH        = 4;

     parameter AXI5_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI5_WRITE_ONLY             = 0;
     parameter AXI5_READ_ONLY              = 0;
     parameter AXI5_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI5_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI5_CMD_FIFO_AWIDTH        = 4;

     parameter AXI6_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI6_WRITE_ONLY             = 0;
     parameter AXI6_READ_ONLY              = 0;
     parameter AXI6_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI6_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI6_CMD_FIFO_AWIDTH        = 4;

     parameter AXI7_DATA_WIDTH             = AXI_DATA_WIDTH;
     parameter AXI7_WRITE_ONLY             = 0;
     parameter AXI7_READ_ONLY              = 0;
     parameter AXI7_SN_WIDTH               = MAX_SN_WIDTH;
     parameter AXI7_SINGLE_CLOCK_MODE      = AXI_SINGLE_CLOCK_MODE;
     parameter AXI7_CMD_FIFO_AWIDTH        = 4;



     parameter SDRAM_BANKSTATMODULES       = 8;
     parameter QUEUE_DEPTH                 = 3;   // Controller Queue Depth
     parameter QM_COMMAND_PIPE_STAGES      = 2;   // Number of pipe stages in queuing module
     parameter FASTSDRAM_PIPE_LEVEL        = 0;   // Sets the pipeline level within fastsdram
                                                  // 0 - normal
                                                  // 1 - uses combinitorial outputs from openbank and openrank and registers
                                                  //     the results of intermediate calculations.  this setting adds no additional latency
     parameter LOOKAHEAD_PRECHARGE         = 0;   // Enables lookahead precharge (change to 0 if the user ties l_auto_pch to 1'b1)
     parameter LOOKAHEAD_AUTOPRECHARGE     = 0;   // Enables lookahead autoprecharge(generates more logic)
     parameter FAST_ACTIVATE               = 0;   // If 1, Activate is not pipelined with QM_COMMAND_PIPE_STAGES > 1
     parameter PD_SR_SUPPORTED             = 0;   // If set to zero, allows logic minimization functionality related to power down or self-refresh
     parameter BURST_SIZE_WIDTH            = 11;   // Width of l_b_size parameter
     parameter BURST_SIZE_WIDTH_LB         = (BURST_SIZE_WIDTH == 'd13) ? 'd11 : BURST_SIZE_WIDTH;   // Width of l_b_size parameter
     parameter PIPELINE_CFG_REGS           = 0;   // Adds pipelining to configuration registers to ease timing when connected to CSR maps
     parameter VPORT_ID_WIDTH              = 1;   // Virtual Port ID width
     parameter BYTES_PER_WORD              = DSIZE/8;
     parameter ADDR_WIDTH                  = 34;  // Local side address width
     parameter BYTE_SUBADDRESS_BITS        =(BYTES_PER_WORD      ==2)  ? 1 :
      (BYTES_PER_WORD      ==4)  ? 2 :
      (BYTES_PER_WORD      ==8)  ? 3 :
      (BYTES_PER_WORD      ==16) ? 4 :
      (BYTES_PER_WORD      ==32) ? 5 :
                                                                          6; //(BYTES_PER_WORD      ==64)
     parameter BYTE_ADDR_WIDTH             = ADDR_WIDTH-1+BYTE_SUBADDRESS_BITS;

     parameter NUM_ALERT_OR_QERR           = 1; //number of parity error inputs(typically 1, higher if there is more than one DIMM interface)

     // ECC-Related Parameters
     parameter ECC_ACTIVE_DWIDTH           =(DSIZE/2/FREQ_RATIO > 64) ? 
                                                 DSIZE/2/FREQ_RATIO/2 : // for 64 < active dwidth <= 128 we need twice as many ECC modules(cannot have more than 64 data per ECC)
                                                 DSIZE/2/FREQ_RATIO ;  
                                                 // Size of actual data that is used for ECC generation.  Example use case:  DDR memory type with DQ = 32.
                                                 //  Set ECC_ACTIVE_DWIDTH to 32 to use 2 ECC instanes, one for rising and one for falling edge data.
                                                 //  Valid settings are 8, 16, 32,48, 56 and 64
     parameter NUM_ECC                     = DSIZE/ECC_ACTIVE_DWIDTH; //number of parallel ECC modules

`ifdef EF_ECC
     parameter ECC_ENABLE                  = 1;   // enable ECC bits
`else
     parameter ECC_ENABLE                  = 0;   // enable ECC bits
`endif
     parameter SYNDROME_REG_PIPELINE       = 0;   // pipeline read ecc checker
     parameter ECC_RDDATA_PIPELINE         = 0;   // pipeline ecc corrected read data

     parameter RMW_WRDATA_PIPELINE         = 0;   // Use to pipeline output write data from RMW
     parameter LB_WRDATA_PIPELINE          = 0;   // Use to pipeline write data from local bus

     parameter OVERRIDE_EARLY_D_REQ        = 0;
     parameter OVERRIDE_EARLY_R_VALID      = 0;
     // DFI parameters
     parameter DFI_DATA_WIDTH              =(ECC_ENABLE == 1 ? DSIZE +(NUM_ECC*8): DSIZE);
     parameter DFI_DATA_PHASE_WIDTH        = DFI_DATA_WIDTH/FREQ_RATIO;
     parameter DFI_DATA_ENABLE_WIDTH       = DFI_DATA_WIDTH/16/(FREQ_RATIO);
     parameter NUM_DQS_LANES               = DFI_DATA_WIDTH/16*(NIBBLE_DEVICES+1) /(FREQ_RATIO); //number of DQS lanes

     parameter ALLOW_PARTIAL_BURSTS        = 0; // 0: dfi_rddata_en will always be full burst lengths - always uses rddata_valid from phy
     parameter USE_PHY_RDDATA_VALID        = 0; // Use dfi_rddata_valid from partial-burst compatible PHY to generate l_r_valid(can only be used with ALLOW_PARTIAL_BURSTS=1)
parameter CAC_PIPE_STAGES             = 2; // Number of pipe stages to add to command/address/control signals.

     parameter DESELECT_WHEN_IDLE          = 1; // 0 Ranks stay selected(CS_N = 0) after commands, 1 CS_N goes high after commands
     parameter MASK_R_VALID_START_EN       = 0; // Enables feature where r_valid can be masked at the start of a read burst for misaligned address. This is used in conjunction with multiburst, so that a full-rate, misaligned read with address of 2, does not have to be broken up into two separate reads in order to deal with misaligned burst order sequence of DDR(interleaved mode), DDR2, DDR3, DDR4, LPDDR2, and LPDDR3. By forcing the sdram address to 0, and masking the first r_valid cycle, a full-rate read starting at address 2, l_b_size = 3, can be performed in a single burst, thereby improving efficiency for these accesses. It is ok to leave this set for configurations other than full-rate, although it doesn't provide the same benefit since an address of 2 is not valid in those cases anyway.
     parameter ENABLE_REG_D_REQ_OUTPUT     = 0; // 0 - l_d_req output is combinatorial
                                                // 1 - l_d_req output is registered(increases minimum supported value of cfg_dfi_t_phy_wrlat)
     // CORE_ADV_WR_START - Advance wr_start coming out of core. Set to 1 to enable cfg_dfi_t_phy_wrlat = 0, at the expense
     //              of not supporting WL+AL+EL < 3
parameter CORE_ADV_WR_START            = 1;
     // CORE_ADV_D_REQ - Advance core_d_req coming out of core. Set to larger values to support larger values of EARLY_D_REQ.
     //              Larger values impose lower limit on WL+AL+EL(see fastsdram.v for description)
parameter CORE_ADV_D_REQ               = 2;
     // CORE_ADV_RD_START - Advance rd_start coming out of core. Set to advance rd_start(value is N/A since rd_start is currently unused)
     parameter CORE_ADV_RD_START            = 0;
     // CORE_ADV_R_VALID - Advance core_r_valid coming out of core. Larger values impose lower limit on CL+AL+EL(see fastsdram.v for description)
     parameter CORE_ADV_R_VALID             = 0;
     parameter USE_READ_CAPTURE_MODULE      = 1;  // Set to include the init_read_capture module in the design
     parameter ENABLE_3DS                   = 1;  // set to include cfg_num_logical_ranks_per_3ds DDR4 3DS logic
     parameter DFI_T_PHY_WRDATA             = 1;   // memory clocks between dfi_wrdata_en_pN and dfi_wrdata_pN
	 parameter ADDR_WIDTH_TS =(EF_RMW_PAR == 1) ? BYTE_ADDR_WIDTH : ADDR_WIDTH;

     parameter MULTIBURST_LATENCY_MASK     = 3'b001;   // Latency of multiburst module(1 = 0 clocks,2 = 1 clock, or 4 = 2 clocks)
parameter MPFE_PIPELINE_VERSION       = 1;        // MPFE pipeline setting -- sets MPFE latency.  Use highest pipelining for FPGA.  See mpfe for details.
 
///////////////////////////////////////////////////
//  MORE PARAMETERS
////////////////////////////////////
     parameter NUM_CAC_BUSES                   = 1;                                   // Number of address,control busses. Also instantiates a second mem_subsystem
     parameter NUM_CLK_OUTS                    = 2;                                   // Number of differential clock output pairs generated
     
     // DFI parameters
     parameter DFI_DATA_PHASE_WIDTH_PHY         = DFI_DATA_WIDTH/FREQ_RATIO;
     parameter DFI_DATA_ENABLE_WIDTH_PHY        = DFI_DATA_WIDTH/16 /(FREQ_RATIO);
     parameter DFI_ADDRESS_WIDTH               = 20;
     parameter DFI_BANK_WIDTH                  = 4;
     parameter DFI_BANKGROUP_WIDTH             = 2;
     parameter DFI_CONTROL_WIDTH               = 1;
     parameter DFI_CHIP_SELECT_WIDTH           = 2;
     parameter DFI_CID_WIDTH                   = 3;
     parameter DFI_WRLVL_SLICE_WIDTH           = NUM_DQS_LANES;                       // width of dfi_wrlvl_resp port
     parameter DFI_DM_PHASE_WIDTH_PHY          =((DFI_DATA_PHASE_WIDTH_PHY+15)/16)*2;    // Round up if DFI_DATA_PHASE_WIDTH is not a multiple of 16, to handle odd width byte lanes(i.e. 32+4 dq)
     parameter DFI_DM_PHASE_WIDTH              =((DFI_DATA_PHASE_WIDTH+15)/16)*2;    // Round up if DFI_DATA_PHASE_WIDTH is not a multiple of 16, to handle odd width byte lanes(i.e. 32+4 dq)
     parameter DFI_ADDRESS_WIDTH_C = 20;
    `ifdef EF_AXI
      `ifdef EF_RMW
         parameter RD_WRAP_ENABLE = 1;
	  `else
         parameter RD_WRAP_ENABLE = 0;
      `endif
	`else
        parameter RD_WRAP_ENABLE = 0;
    `endif // `ifdef EF_AXI
 ///////////////////////////////////////////////////////////////////////////////////////
 //
 // I/O Ports
 //
 // clocks and reset
 input                                reset_n; // System Reset
 // local interface ports

 input                                l_r_req; // Read Request
 input                                l_w_req; // Write Request

 input [ADDR_WIDTH_TS-1:0]            l_addr; // Memory Address to read/write - ADDR_WIDTH because EF_RWM not defined
 input [BURST_SIZE_WIDTH_LB-1:0]      l_b_size; // Burst Size
 input                                l_rd_wrap; // Read wrap control
 input                                l_w_rmw; // Write Masking used when read-modify-write is required
 input                                l_auto_pch; // Auto Precharge Request
 output                               l_busy; // Controller busy.  Command registered by controller when
 output                               l_r_valid; // Read Data Valid
 output                               l_d_req; // Data Request
 input [DSIZE-1:0]                    l_datain; // Write data
 input [DSIZE/8-1:0]                  l_dm_in; // Write data mask 

 // AXI globals
 input                                axi0_aclk;
 input                                axi0_aresetn;
 // AXI Slave write address
 input [(AXI_SLAVE_ID_WIDTH-1):0]     axi0_awid;
 input [(AXI_ADDR_WIDTH-1):0]         axi0_awaddr;
 input [(AXI_LEN_WIDTH-1):0]          axi0_awlen;
 input [2:0]                          axi0_awsize;
 input [1:0]                          axi0_awburst;
 input [1:0]                          axi0_awlock;
 input [3:0]                          axi0_awcache;
 input [2:0]                          axi0_awprot;
 input                                axi0_awvalid;
 output                               axi0_awready;
 // AXI Slave write data
 input [(AXI_SLAVE_ID_WIDTH-1):0]     axi0_wid;
 input [(AXI0_DATA_WIDTH-1):0]        axi0_wdata;
 input [((AXI0_DATA_WIDTH>>3)-1):0]   axi0_wstrb;
