 output [TAG_WIDTH-1:0]               l_r_valid_tag; // Tag corresponding to l_r_valid



 // Miscellaneous user controls
 input [NUMBER_OF_RANKS-1:0]          l_self_refresh;
 input [NUMBER_OF_RANKS-1:0]          l_power_down;     // SDRAM power down control; 1 = put devices into power down mode;
                                                        //                           0 = normal operation.
 input                                l_d_power_down;   // 1 = put ranks into deep power down when any l_power_down is asserted.
                                                        // 0 = normal power down operation

 input                                l_ref_req;        // Refresh Request
 output                               l_ref_ack;        // Refresh Acknowledge
 output [4:0]                         l_queue_level;    // Monitoring signals about how many command occupy internal queue
 output [SDRAM_BANKSTATMODULES-1:0]   l_activate_ready; // monitoring signal about activation status considering qm inside command
 input [NUMBER_OF_RANKS-1:0]          l_zq_cal_req; // Request ZQCL or ZQCS or ZQRESET(LPDDR2 only)(depends on setting of cfg_zq_cal_type)
 output                               l_zq_cal_ack; // Acknowledge of ZQCL or ZQCS or ZQRESET(LPDDR2 only)

 output wire [DSIZE-1:0]              l_dataout; // Local data out
 output wire [NUM_ECC*8-1:0]          l_ecc_check_dataout; // ECC check data associated with l_dataout

 output [1023:0]                       mpfe_status;

