 output [NUM_ECC-1:0]                 ecc_error_2bit;
 output [NUM_ECC*7-1:0]               ecc_error_pos;
 output                               ecc_rmw_error;
 output [BYTE_ADDR_WIDTH-1:0]         ecc_error_addr; // address of the errored read

